import copy

def step(grid: list[list[int]], action: int, x: int = -1, y: int = -1) -> list[list[int]]:
    """
    Simulates one step of the grid game.

    The game involves moving a 6x6 "player" object (color 6) vertically through a series of 
    "slots" or "lanes". Each slot contains a 6x2 pattern of colors 1 and 2 that can be 
    "activated" (turned to color 4) or "deactivated" (turned back to 1/2).

    Actions:
    - 1: Move player UP
    - 2: Move player DOWN
    - 3: Activate the pattern in the current slot (turn 1/2 -> 4)
    - 4: Deactivate the pattern in the current slot (turn 4 -> 1/2)
    - 7: Toggle the pattern in the current slot (if active, deactivate; if inactive, activate)
    - 6: Click (no effect in this game logic based on observations)
    - 0: Reset (not implemented as we don't have the initial state stored)

    The player object is a 6x6 square with a specific internal pattern:
    - Border is color 6
    - Interior has a pattern of 0s and other colors

    The slots are located at specific y-coordinates. The player moves between these slots.
    When the player is in a slot, actions 3, 4, and 7 affect the 6x2 pattern to the right of the player.

    There is also a counter at the bottom of the screen (row 53) that increments when a pattern 
    is deactivated (action 4 or 7 when active). The counter is represented by a sequence of 2s 
    followed by a 3. The position of the 3 moves left as the counter increments.
    """

    new_grid = copy.deepcopy(grid)

    # Find the player's current position
    player_y = -1
    for r in range(64):
        for c in range(64):
            if new_grid[r][c] == 6:
                # Check if this is part of the player object (6x6 square)
                # The player is a 6x6 square, so we look for the top-left corner
                if (r <= 58 and c <= 58 and 
                    all(new_grid[r+dy][c+dx] == 6 or 
                        (dy > 0 and dy < 5 and dx > 0 and dx < 5 and new_grid[r+dy][c+dx] != 5)
                        for dy in range(6) for dx in range(6) 
                        if 0 <= r+dy < 64 and 0 <= c+dx < 64)):
                    # More precise check: look for the 6x6 block structure
                    is_player = True
                    for dy in range(6):
                        for dx in range(6):
                            ny, nx = r + dy, c + dx
                            if ny >= 64 or nx >= 64:
                                is_player = False
                                break
                            val = new_grid[ny][nx]
                            # Border should be 6
                            if dy == 0 or dy == 5 or dx == 0 or dx == 5:
                                if val != 6:
                                    is_player = False
                                    break
                            # Interior can be 0 or other colors
                        if not is_player:
                            break
                    if is_player:
                        player_y = r
                        player_x = c
                        break
        if player_y != -1:
            break

    if player_y == -1:
        # Player not found, return grid unchanged
        return new_grid

    # Define the player's bounding box
    p_top = player_y
    p_left = player_x
    p_bottom = player_y + 5
    p_right = player_x + 5

    # The pattern to the right of the player is at columns p_right+1 to p_right+6, rows p_top to p_top+1
    pattern_left = p_right + 1
    pattern_top = p_top
    pattern_width = 6
    pattern_height = 2

    def get_pattern_cells():
        cells = []
        for dy in range(pattern_height):
            for dx in range(pattern_width):
                cells.append((pattern_left + dx, pattern_top + dy))
        return cells

    def is_pattern_active():
        cells = get_pattern_cells()
        for cx, cy in cells:
            if new_grid[cy][cx] != 4:
                return False
        return True

    def activate_pattern():
        cells = get_pattern_cells()
        # The pattern has a specific structure of 1s and 2s
        # When activated, all become 4
        for cx, cy in cells:
            new_grid[cy][cx] = 4

    def deactivate_pattern():
        cells = get_pattern_cells()
        # Restore the original 1/2 pattern
        # The pattern is:
        # Row 0: 2 1 1 2 1 1
        # Row 1: 1 1 2 1 1 2
        pattern_row0 = [2, 1, 1, 2, 1, 1]
        pattern_row1 = [1, 1, 2, 1, 1, 2]
        for dx in range(pattern_width):
            new_grid[pattern_top][pattern_left + dx] = pattern_row0[dx]
            new_grid[pattern_top + 1][pattern_left + dx] = pattern_row1[dx]

        # Increment the counter
        # The counter is at row 53, starting from the right
        # Find the rightmost 3 in row 53
        counter_pos = -1
        for cx in range(63, -1, -1):
            if new_grid[53][cx] == 3:
                counter_pos = cx
                break

        if counter_pos > 0:
            new_grid[53][counter_pos] = 2
            new_grid[53][counter_pos - 1] = 3

    def move_player_up():
        nonlocal player_y, player_x, p_top, p_bottom
        # Check if we can move up
        # The player moves in discrete steps between slots
        # Slots are at specific y positions
        # Try to move up by 6 rows
        new_y = player_y - 6
        if new_y < 0:
            return False

        # Check if the new position is valid (not overlapping with walls)
        # The player is a 6x6 square
        for dy in range(6):
            for dx in range(6):
                ny, nx = new_y + dy, player_x + dx
                if ny < 0 or ny >= 64 or nx < 0 or nx >= 64:
                    return False
                # Check if the cell is a wall (color 5 or 4)
                if new_grid[ny][nx] in [5, 4]:
                    return False
        return True

    def move_player_down():
        nonlocal player_y, player_x, p_top, p_bottom
        new_y = player_y + 6
        if new_y + 5 >= 64:
            return False

        for dy in range(6):
            for dx in range(6):
                ny, nx = new_y + dy, player_x + dx
                if ny < 0 or ny >= 64 or nx < 0 or nx >= 64:
                    return False
                if new_grid[ny][nx] in [5, 4]:
                    return False
        return True

    def clear_player():
        # Clear the player from its current position
        for dy in range(6):
            for dx in range(6):
                ny, nx = player_y + dy, player_x + dx
                if 0 <= ny < 64 and 0 <= nx < 64:
                    # Restore the background
                    if dy == 0 or dy == 5 or dx == 0 or dx == 5:
                        new_grid[ny][nx] = 5  # Border was 6, background is 5
                    else:
                        # Interior cells
                        if dy == 1 or dy == 4:
                            if dx == 1 or dx == 4:
                                new_grid[ny][nx] = 0
                            else:
                                new_grid[ny][nx] = 5
                        elif dy == 2 or dy == 3:
                            if dx == 1 or dx == 4:
                                new_grid[ny][nx] = 0
                            elif dx == 2 or dx == 3:
                                # These are the pattern cells, but they're part of the player
                                # Actually, the player's interior is 0s and the pattern is separate
                                new_grid[ny][nx] = 5
                        else:
                            new_grid[ny][nx] = 5

    def draw_player(y, x):
        # Draw the player at the new position
        for dy in range(6):
            for dx in range(6):
                ny, nx = y + dy, x + dx
                if 0 <= ny < 64 and 0 <= nx < 64:
                    if dy == 0 or dy == 5 or dx == 0 or dx == 5:
                        new_grid[ny][nx] = 6
                    else:
                        if dy == 1 or dy == 4:
                            if dx == 1 or dx == 4:
                                new_grid[ny][nx] = 0
                            else:
                                new_grid[ny][nx] = 5
                        elif dy == 2 or dy == 3:
                            if dx == 1 or dx == 4:
                                new_grid[ny][nx] = 0
                            else:
                                new_grid[ny][nx] = 5
                        else:
                            new_grid[ny][nx] = 5

    if action == 1:  # Move up
        if move_player_up():
            clear_player()
            player_y -= 6
            p_top = player_y
            p_bottom = player_y + 5
            draw_player(player_y, player_x)

    elif action == 2:  # Move down
        if move_player_down():
            clear_player()
            player_y += 6
            p_top = player_y
            p_bottom = player_y + 5
            draw_player(player_y, player_x)

    elif action == 3:  # Activate pattern
        activate_pattern()

    elif action == 4:  # Deactivate pattern
        if is_pattern_active():
            deactivate_pattern()

    elif action == 7:  # Toggle pattern
        if is_pattern_active():
            deactivate_pattern()
        else:
            activate_pattern()

    elif action == 6:  # Click - no effect
        pass

    elif action == 0:  # Reset - not implemented
        pass

    return new_grid

def goal(grid: list[list[int]]) -> bool:
    """
    Returns True if the level is completed.
    Based on the observations, the level is completed when the counter at the bottom
    reaches a certain value. The counter is represented by a sequence of 2s followed by a 3
    in row 53. When the 3 reaches the leftmost position (column 0), the level is complete.
    """
    # Check if the counter has reached the leftmost position
    for cx in range(64):
        if grid[53][cx] == 3:
            return cx == 0
    return False
